mapper.select:
SELECT COALESCE(t.title, '템플릿 ' || ts.template_id) AS name, CASE WHEN SUM(COALESCE(ts.click_target_count, 0)) = 0 THEN 0 ELSE ROUND((SUM(COALESCE(ts.click_count, 0)) / SUM(COALESCE(ts.click_target_count, 0))) * 100, 1) END AS click, CASE WHEN SUM(COALESCE(ts.conversion_target_count, 0)) = 0 THEN NULL ELSE ROUND((SUM(COALESCE(ts.conversion_count, 0)) / SUM(COALESCE(ts.conversion_target_count, 0))) * 100, 1) END AS conversion, CASE WHEN COALESCE(t.is_ai_generated, 0) = 1 THEN 'AI 템플릿' ELSE '기본 템플릿' END AS source FROM template_stat ts LEFT JOIN template t ON t.id = ts.template_id AND t.is_deleted = 0 WHERE ts.is_deleted = 0
AND ts.stat_date >= #{from}
AND ts.stat_date <= #{to}
GROUP BY ts.template_id, t.title, t.is_ai_generated ORDER BY CASE WHEN SUM(COALESCE(ts.click_target_count, 0)) = 0 THEN 0 ELSE SUM(COALESCE(ts.click_count, 0)) / SUM(COALESCE(ts.click_target_count, 0)) END DESC, SUM(COALESCE(ts.click_count, 0)) DESC FETCH FIRST 5 ROWS ONLY
